"""items_observed.py : writes docs/items_observed.md (item hash key frequency across all unique user saves). No names are guessed."""
import sys, os, json, collections; sys.path.insert(0, os.path.dirname(__file__))
import corpus
recs = corpus.load(); N = len(recs); CAT = {e["key"]: e for e in json.load(open(os.path.join(corpus.INV.ROOT, "docs", "items.json")))["items"]}; L = lambda r, p: r["leaves"].get(p)
K = collections.defaultdict(lambda: dict(saves=set(), num=collections.Counter(), knum=set(), flag=collections.Counter()))
for i, r in enumerate(recs):
    for sec, idx, e in r["items"]:
        if e["key"] == 0 and e["num"] == 0: continue
        k = K[e["key"]]; k["saves"].add(i); k["num"][e["num"]] += 1; k["knum"].add(e["key_num"]); k["flag"][e["flag"]] += 1
fq = collections.Counter(len(v["saves"]) for v in K.values())
lines = ["# Items observed across the sample saves", "",
 f"**Observed in {N} unique user saves, uncontrolled** (other players' saves; no experiment; saves of one player are correlated, so a key's frequency mostly reflects how far into the game that player's slots are). Generated by `tools/items_observed.py`. **Names:** the only names are the nine in `docs/items.json`, taken from a community Cheat Engine table (**third-party, not a controlled experiment**, from a different game build). They are `likely` at most; **`confirmed` needs our own experiment #2** (before/after saves plus the in-game item name and count, see `docs/experiments.md`). Two more keys are deliberately unnamed because the same table treats them specially. Every other key has no name.", "",
 "## Summary", "",
 f"- {len(K)} distinct non-empty item keys; all are < 2^31 and their low byte is always one of 0x00, 0x7F, 0x80 or 0xFF (a hash with a 2-bit tag, guess).",
 f"- Only `possession_items` is ever populated ({sum(1 for r in recs for s, i, e in r['items'] if s == 'possession_items' and not (e['key'] == 0 and e['num'] == 0)):,} rows); `storage_items` is empty in every save.",
 "- Within one save a key occurs in at most one row (no duplicate keys): stacks are a single row, so `num` is the stack count (26 keys reach `num` > 1, up to 420 on ordinary rows, and exactly 99999 on 2 keys in 6 rows (player A and player B's NG+ set); supports the `item.num` = quantity guess, still not confirmed).",
 f"- The nine named keys occur in 31-41 of the {N} saves; `num` for Type-14 Film is never below 14. Quantity-like behaviour: rows stay at 0 after use (a row with `num` 0 exists for 4 of the named keys).",
 "- **Stacks above 99:** only two keys ever go above 99: Prayer Beads (`0x4F9CE17F`: 128, 146, 420 in 10 saves, 99999 in 3) and the unnamed `0x7A5EBCFF` (99999 in 3 saves, 50 in 10). A community 'max stack = 99' routine would not explain either. Exactly 99 appears on 9 rows in each of three saves of one player (8 of the 9 named items), which looks like a tool-maxed state, not a natural cap.",
 "- Note: the 'special' key `0x179D3D00` (Stone Mirror) is 99 in those three saves although the same table excludes it from its 99 routine.",
 "- `key_num` is **not** an item property: for the same key it differs between saves (only 4 of 246 keys seen in at least 5 rows keep one value), it is unique across rows inside each save, and it is <= `PlayerData/item_object_unique_number` in 42 of 42 saves. Consistent with a per-instance id drawn from that counter. `entry_number` behaves the same way against `item_object_entry_number`.",
 "- 53 rows have a key but `num` = 0 (placeholders?). `flag` is 1 in 5,730 rows and 257 (0x101) in 322 rows.",
 f"- Keys present in all {N} saves: 0; in at least 40 saves: {sum(1 for v in K.values() if len(v['saves']) >= 40)}; in exactly one save: {fq[1]}.", "",
 "## Frequency table (sorted by number of saves, then key)", "",
 "| key (dec) | key (hex) | name (source: third-party cheat table, uncontrolled) | saves | num min-max | most common num | key_num distinct | flag values |", "|---|---|---|---|---|---|---|---|"]
for key, v in sorted(K.items(), key=lambda kv: (-len(kv[1]["saves"]), kv[0])):
    c = CAT.get(key); nm = (f"{c['name']} ({c.get('confidence', 'guessed')})" if c and c.get("name") else (c["note"] if c else "-"))
    lines.append(f"| {key} | 0x{key:08X} | {nm} | {len(v['saves'])}/{N} | {min(v['num'])}-{max(v['num'])} | {v['num'].most_common(1)[0][0]} | {len(v['knum'])} | {','.join(map(str, sorted(v['flag'])))} |")
open(os.path.join(corpus.INV.ROOT, "docs", "items_observed.md"), "w").write("\n".join(lines) + "\n")
print(len(lines), "lines written;", len(K), "keys")
